package com.citacloud.springboot.contacloud.app.views;
import com.citacloud.springboot.contacloud.app.dto.*;import com.citacloud.springboot.contacloud.app.models.*;import com.citacloud.springboot.contacloud.app.security.TenantContext;import com.citacloud.springboot.contacloud.app.services.*;import com.citacloud.springboot.contacloud.app.views.components.*;import com.vaadin.flow.component.*;import com.vaadin.flow.component.combobox.ComboBox;import com.vaadin.flow.component.confirmdialog.ConfirmDialog;import com.vaadin.flow.component.datepicker.DatePicker;import com.vaadin.flow.component.dialog.Dialog;import com.vaadin.flow.component.grid.Grid;import com.vaadin.flow.component.html.*;import com.vaadin.flow.component.notification.Notification;import com.vaadin.flow.component.orderedlayout.*;import com.vaadin.flow.component.select.Select;import com.vaadin.flow.component.textfield.*;import com.vaadin.flow.data.value.ValueChangeMode;import com.vaadin.flow.router.*;import com.vaadin.flow.server.*;import jakarta.annotation.security.PermitAll;import java.io.ByteArrayInputStream;import java.math.BigDecimal;import java.text.DecimalFormat;import java.time.*;import java.time.format.DateTimeFormatter;import java.util.*;import java.util.function.Supplier;
@Route(value="inventario/ajustes",layout=MainLayout.class)@PageTitle("Ajustes de inventario | ContaCloud")@PermitAll public class InventarioAjustesView extends VerticalLayout implements BeforeEnterObserver{
 private static final DateTimeFormatter DATE=DateTimeFormatter.ofPattern("dd/MM/yyyy"),TIME=DateTimeFormatter.ofPattern("dd/MM/yyyy HH:mm");private static final DecimalFormat NUMBER=new DecimalFormat("#,##0.####");private final AjusteInventarioService service;private final AjusteInventarioDocumentoService documents;private final EmpresaModuloService modules;private AjusteInventarioCatalogosDto catalogs;private final TextField search=new TextField("Buscar");private final DatePicker from=date("Desde"),to=date("Hasta");private final Select<EstadoAjusteInventario> state=new Select<>();private final ComboBox<AjusteInventarioCatalogosDto.Almacen> warehouse=new ComboBox<>("Almacén");private final Select<TipoAjusteInventario> type=new Select<>();private final ComboBox<AjusteInventarioCatalogosDto.Motivo> reason=new ComboBox<>("Motivo");private final AppGrid<AjusteInventarioDto> grid=new AppGrid<>(AjusteInventarioDto.class);private final AppPagination pagination;
 public InventarioAjustesView(AjusteInventarioService s,EmpresaModuloService m){this(s,null,m);}@org.springframework.beans.factory.annotation.Autowired public InventarioAjustesView(AjusteInventarioService s,AjusteInventarioDocumentoService d,EmpresaModuloService m){service=s;documents=d;modules=m;addClassName("cc-page");setPadding(false);setSpacing(false);setWidthFull();Component add=can("inventario_ajustes.crear")?new AppActionButton(ActionType.NEW,ButtonSize.MAIN,"Nuevo ajuste",e->form(null)):null;add(add==null?new AppPageHeader("AJUSTES DE INVENTARIO","Corrige existencias mediante movimientos trazables y auditados."):new AppPageHeader("AJUSTES DE INVENTARIO","Corrige existencias mediante movimientos trazables y auditados.",add));filters();configureGrid();pagination=new AppPagination(x->load());HorizontalLayout bar=new HorizontalLayout(search,from,to,state,warehouse,type,reason);bar.addClassName("cc-filter-bar");bar.setAlignItems(Alignment.END);bar.setWidthFull();add(bar,grid,pagination);}
 @Override public void beforeEnter(BeforeEnterEvent e){if(!modules.habilitado("INVENTARIO")||!can("inventario_ajustes.ver")){Notification.show("No tienes permiso para acceder a esta opción.");e.rerouteTo(DashboardView.class);return;}try{catalogs=service.catalogos(null);warehouse.setItems(catalogs.almacenes());reason.setItems(catalogs.motivos());load();}catch(RuntimeException x){error(x,"No fue posible cargar los ajustes de inventario.");}}
 private void filters(){search.setPlaceholder("Número, referencia, producto o código...");search.setClearButtonVisible(true);search.setValueChangeMode(ValueChangeMode.LAZY);state.setLabel("Estado");state.setItems(EstadoAjusteInventario.values());state.setItemLabelGenerator(x->x==null?"Todos":x.getEtiqueta());state.setEmptySelectionAllowed(true);state.setEmptySelectionCaption("Todos");type.setLabel("Tipo");type.setItems(TipoAjusteInventario.values());type.setItemLabelGenerator(x->x==null?"Todos":x.getEtiqueta());type.setEmptySelectionAllowed(true);type.setEmptySelectionCaption("Todos");warehouse.setClearButtonVisible(true);warehouse.setItemLabelGenerator(x->x.nombre()+" · "+x.sucursal());reason.setClearButtonVisible(true);reason.setItemLabelGenerator(AjusteInventarioCatalogosDto.Motivo::nombre);for(HasValue<?,?> f:List.of(search,from,to,state,warehouse,type,reason))f.addValueChangeListener(e->{if(e.isFromClient()){pagination.reset();load();}});}
 private void configureGrid(){grid.addColumn(x->DATE.format(x.fecha())).setHeader("Fecha").setAutoWidth(true);grid.addColumn(AjusteInventarioDto::numero).setHeader("Número").setAutoWidth(true);grid.addColumn(x->x.almacen()+" · "+x.sucursal()).setHeader("Almacén").setFlexGrow(1);grid.addColumn(AjusteInventarioDto::motivo).setHeader("Motivo").setFlexGrow(1);grid.addColumn(x->x.tipo().getEtiqueta()).setHeader("Tipo").setAutoWidth(true);grid.addComponentColumn(x->badge(x.estado())).setHeader("Estado").setAutoWidth(true);grid.addComponentColumn(this::actions).setHeader("Acciones").setAutoWidth(true).setFlexGrow(0);grid.setEmptyStateText("No hay ajustes de inventario registrados.");}
 private Component actions(AjusteInventarioDto a){HorizontalLayout h=new HorizontalLayout();h.addClassName("cc-grid-actions");h.setPadding(false);h.setSpacing(false);h.add(new AppActionButton(ActionType.VIEW,ButtonSize.GRID_ACTION,"Ver ajuste",e->detail(a.id())));if(a.estado()==EstadoAjusteInventario.DRAFT&&can("inventario_ajustes.editar"))h.add(new AppActionButton(ActionType.EDIT,ButtonSize.GRID_ACTION,"Editar ajuste",e->form(a.id())));return h;}
 private void load(){if(catalogs==null)return;try{var r=pagination.currentRequest();var p=service.buscar(search.getValue(),from.getValue(),to.getValue(),state.getValue(),id(warehouse),type.getValue(),id(reason),r.page(),r.size());grid.setItems(p.getContent());pagination.setTotal(p.getTotalElements());}catch(RuntimeException e){error(e,"No fue posible cargar los ajustes de inventario.");}}
 private void form(UUID id){try{AjusteInventarioDto current=id==null?null:service.obtener(id);AjusteInventarioCatalogosDto initial=service.catalogos(current==null?null:current.almacenId());Dialog d=dialog(current==null?"NUEVO AJUSTE":"EDITAR AJUSTE",1200);DatePicker effective=date("Fecha");effective.setRequiredIndicatorVisible(true);effective.setValue(current==null?LocalDate.now():current.fecha());ComboBox<AjusteInventarioCatalogosDto.Almacen> w=new ComboBox<>("Almacén");w.setItems(initial.almacenes());w.setItemLabelGenerator(x->x.nombre()+" · "+x.sucursal());w.setRequiredIndicatorVisible(true);Span branch=new Span("Selecciona un almacén");branch.addClassName("cc-secondary-text");VerticalLayout wb=new VerticalLayout(w,branch);wb.setPadding(false);wb.setSpacing(false);wb.setWidthFull();w.setWidthFull();ComboBox<AjusteInventarioCatalogosDto.Motivo> m=new ComboBox<>("Motivo");m.setItems(initial.motivos());m.setItemLabelGenerator(x->x.nombre()+" · "+x.direccion().getEtiqueta());m.setRequiredIndicatorVisible(true);TextField ref=new TextField("Referencia");ref.setMaxLength(100);TextArea notes=new TextArea("Observación");notes.setMaxLength(1000);notes.addClassName("cc-dialog-span-2");List<LineDraft> drafts=new ArrayList<>();if(current!=null){select(w,current.almacenId());select(m,current.motivoId());ref.setValue(value(current.referencia()));notes.setValue(value(current.observacion()));for(var l:current.lineas()){var p=initial.productos().stream().filter(x->x.id().equals(l.productoId())).findFirst().orElse(new AjusteInventarioCatalogosDto.Producto(l.productoId(),l.codigo(),l.producto(),l.unidadId(),l.unidad(),l.saldoAnterior()==null?BigDecimal.ZERO:l.saldoAnterior(),false));drafts.add(new LineDraft(p,l.ajuste()));}}w.addValueChangeListener(e->{branch.setText(e.getValue()==null?"Selecciona un almacén":e.getValue().sucursal());if(e.isFromClient()&&!drafts.isEmpty()){ConfirmDialog c=new ConfirmDialog("Cambiar almacén","Cambiar el almacén eliminará los productos agregados al ajuste. ¿Desea continuar?","Continuar",x->{drafts.clear();},"Cancelar",x->{});c.open();}});AppGrid<LineDraft> table=new AppGrid<>(LineDraft.class);table.addColumn(x->x.product.codigo()).setHeader("Código").setAutoWidth(true);table.addColumn(x->x.product.nombre()).setHeader("Producto").setFlexGrow(1);table.addColumn(x->x.product.unidad()).setHeader("Unidad").setAutoWidth(true);table.addColumn(x->number(x.product.existencia())).setHeader("Existencia actual").setAutoWidth(true);table.addColumn(x->signed(x.quantity)).setHeader("Ajuste").setAutoWidth(true);table.addColumn(x->number(x.product.existencia().add(x.quantity))).setHeader("Existencia resultante").setAutoWidth(true);table.addComponentColumn(x->new AppActionButton(ActionType.DELETE,ButtonSize.GRID_ACTION,"Eliminar producto",e->{drafts.remove(x);table.setItems(drafts);})).setHeader("Acciones").setAutoWidth(true);table.setItems(drafts);AppActionButton addLine=new AppActionButton(ActionType.NEW,ButtonSize.MAIN,"Agregar producto",e->lineForm(w,m,drafts,null,table));Div lineHead=new Div(new H3("PRODUCTOS"),addLine);lineHead.addClassName("cc-detail-heading");d.add(section("INFORMACIÓN GENERAL",effective,wb,m,ref,notes),lineHead,table);if(current==null||current.estado()==EstadoAjusteInventario.DRAFT){Supplier<AjusteInventarioInput> input=()->new AjusteInventarioInput(effective.getValue(),id(w),id(m),ref.getValue(),notes.getValue(),current==null?null:current.version(),drafts.stream().map(x->new AjusteInventarioInput.Linea(x.product.id(),x.product.unidadId(),x.quantity)).toList());AppActionButton save=new AppActionButton(ActionType.SAVE,ButtonSize.MAIN,"Guardar",e->{try{if(current==null)service.crear(input.get());else service.actualizar(current.id(),input.get());d.close();refresh();Notification.show("Ajuste guardado como borrador.");}catch(RuntimeException x){error(x,"No fue posible guardar el ajuste.");}});AppActionButton confirm=new AppActionButton(ActionType.ISSUE,ButtonSize.MAIN,"Confirmar ajuste",e->confirm("CONFIRMAR AJUSTE DE INVENTARIO","Este ajuste modificará las existencias del almacén.",()->{try{var a=service.guardarYConfirmar(current==null?null:current.id(),input.get());d.close();refresh();Notification.show("Ajuste confirmado.");openPdfAfter(a);}catch(RuntimeException x){error(x,"No fue posible confirmar el ajuste.");}}));d.getFooter().add(save,confirm);}d.getFooter().add(new AppActionButton(ActionType.CANCEL,ButtonSize.MAIN,"Cancelar",e->d.close()));d.open();}catch(RuntimeException e){error(e,"No fue posible abrir el ajuste.");}}
 private void lineForm(ComboBox<AjusteInventarioCatalogosDto.Almacen>w,ComboBox<AjusteInventarioCatalogosDto.Motivo>m,List<LineDraft>drafts,LineDraft current,Grid<LineDraft>table){if(w.getValue()==null){Notification.show("Selecciona primero el almacén.");return;}try{var available=service.catalogos(w.getValue().id()).productos();Dialog d=dialog(current==null?"AGREGAR PRODUCTO":"EDITAR PRODUCTO",700);ComboBox<AjusteInventarioCatalogosDto.Producto> p=new ComboBox<>("Producto");p.setItems(available);p.setItemLabelGenerator(x->x.codigo()+" · "+x.nombre()+" · Existencia: "+number(x.existencia()));p.setRequiredIndicatorVisible(true);BigDecimalField q=new BigDecimalField("Ajuste (+ entrada / - salida)");q.setRequiredIndicatorVisible(true);Span resulting=new Span("Existencia resultante: —");q.addValueChangeListener(e->{if(p.getValue()!=null&&e.getValue()!=null)resulting.setText("Existencia resultante: "+number(p.getValue().existencia().add(e.getValue())));});p.addValueChangeListener(e->{if(e.getValue()!=null&&q.getValue()!=null)resulting.setText("Existencia resultante: "+number(e.getValue().existencia().add(q.getValue())));});if(current!=null){p.setValue(available.stream().filter(x->x.id().equals(current.product.id())).findFirst().orElse(current.product));q.setValue(current.quantity);}d.add(section("PRODUCTO",p,q,resulting));d.getFooter().add(new AppActionButton(ActionType.SAVE,ButtonSize.MAIN,"Guardar línea",e->{try{var product=p.getValue();if(product==null)throw new ReglaNegocioException("Selecciona un producto.");if(q.getValue()==null||q.getValue().signum()==0)throw new ReglaNegocioException("La cantidad del ajuste debe ser diferente de cero.");if(m.getValue()==null)throw new ReglaNegocioException("Selecciona el motivo del ajuste.");if(!m.getValue().direccion().permite(q.getValue().signum()))throw new ReglaNegocioException(m.getValue().direccion()==DireccionMotivoAjuste.OUT?"El motivo seleccionado solo permite ajustes de salida.":"El motivo seleccionado solo permite ajustes de entrada.");if(drafts.stream().anyMatch(x->x!=current&&x.product.id().equals(product.id())))throw new ReglaNegocioException("El producto ya fue agregado al ajuste.");LineDraft n=new LineDraft(product,q.getValue());if(current==null)drafts.add(n);else drafts.set(drafts.indexOf(current),n);table.setItems(drafts);d.close();}catch(RuntimeException x){error(x,"No fue posible guardar la línea.");}}),new AppActionButton(ActionType.CANCEL,ButtonSize.MAIN,"Cancelar",e->d.close()));d.open();}catch(RuntimeException e){error(e,"No fue posible cargar los productos.");}}
 private void detail(UUID id){
  try{
   var a=service.obtener(id);Dialog d=dialog("AJUSTE DE INVENTARIO",1200);
   Div heading=new Div(new H2(a.numero()),badge(a.estado()));heading.addClassName("cc-detail-heading");
   d.add(heading,new AppDetailSection("INFORMACIÓN GENERAL")
       .field("Fecha",DATE.format(a.fecha())).field("Almacén",a.almacen()).field("Sucursal",a.sucursal())
       .field("Motivo",a.motivo()).field("Tipo",a.tipo().getEtiqueta()).field("Referencia",display(a.referencia()))
       .field("Observación",display(a.observacion())));
   AppGrid<AjusteInventarioDto.Linea> t=new AppGrid<>(AjusteInventarioDto.Linea.class);
   t.addColumn(AjusteInventarioDto.Linea::codigo).setHeader("Código").setAutoWidth(true);
   t.addColumn(AjusteInventarioDto.Linea::producto).setHeader("Producto").setFlexGrow(1);
   t.addColumn(AjusteInventarioDto.Linea::unidad).setHeader("Unidad").setAutoWidth(true);
   t.addColumn(x->number(x.saldoAnterior())).setHeader("Anterior").setAutoWidth(true);
   t.addColumn(x->signed(x.ajuste())).setHeader("Ajuste").setAutoWidth(true);
   t.addColumn(x->number(x.saldoPosterior())).setHeader("Posterior").setAutoWidth(true);t.setItems(a.lineas());
   d.add(t,new AppDetailSection("AUDITORÍA").field("Confirmado por",display(a.confirmadaPor()))
       .field("Confirmado",time(a.confirmadaEn())).field("Anulado",time(a.anuladaEn()))
       .field("Motivo de anulación",display(a.motivoAnulacion())).field("Revertido",time(a.revertidaEn())));
   if(a.estado()==EstadoAjusteInventario.DRAFT&&can("inventario_ajustes.confirmar"))
    d.getFooter().add(new AppActionButton(ActionType.ISSUE,ButtonSize.MAIN,"Confirmar ajuste",e->confirm(
        "Confirmar ajuste","Se revalidarán las existencias y se generarán los movimientos.",()->{
         try{var x=service.confirmar(a.id());d.close();refresh();openPdfAfter(x);}
         catch(RuntimeException ex){error(ex,"No fue posible confirmar el ajuste.");}})));
   if(a.estado()==EstadoAjusteInventario.DRAFT&&can("inventario_ajustes.anular"))
    d.getFooter().add(new AppActionButton(ActionType.VOID,ButtonSize.MAIN,"Anular borrador",e->reason(
        "ANULAR AJUSTE","Motivo de anulación",r->{service.anular(a.id(),r);d.close();refresh();})));
   if((a.estado()==EstadoAjusteInventario.CONFIRMED||a.estado()==EstadoAjusteInventario.REVERSED)
       &&can("inventario_ajustes.pdf"))
    d.getFooter().add(new AppActionButton(ActionType.PRINT,ButtonSize.MAIN,"Generar PDF",e->{
     try{openPdf(a.id());}catch(RuntimeException x){error(x,"No fue posible generar el PDF del ajuste.");}}));
   if(a.estado()==EstadoAjusteInventario.CONFIRMED&&can("inventario_ajustes.revertir"))
    d.getFooter().add(new AppActionButton(ActionType.REJECT,ButtonSize.MAIN,"Revertir ajuste",e->reason(
        "REVERTIR AJUSTE","Motivo de reversión",r->{service.revertir(a.id(),r);d.close();refresh();})));
   d.getFooter().add(new AppActionButton(ActionType.CLOSE,ButtonSize.MAIN,"Cerrar",e->d.close()));d.open();
  }catch(RuntimeException e){error(e,"No fue posible consultar el ajuste.");}
 }
 private void reason(String title,String label,java.util.function.Consumer<String> action){Dialog d=dialog(title,650);TextArea r=new TextArea(label);r.setRequiredIndicatorVisible(true);r.setWidthFull();d.add(r);d.getFooter().add(new AppActionButton(ActionType.ACCEPT,ButtonSize.MAIN,title,e->{try{action.accept(r.getValue());d.close();}catch(RuntimeException x){error(x,"No fue posible completar la operación.");}}),new AppActionButton(ActionType.CANCEL,ButtonSize.MAIN,"Cancelar",e->d.close()));d.open();}private void openPdfAfter(AjusteInventarioDto a){try{openPdf(a.id());}catch(RuntimeException e){Notification.show("El ajuste fue confirmado correctamente, pero no fue posible generar el PDF. Puede generarlo nuevamente desde el detalle del ajuste.");}}private void openPdf(UUID id){ArchivoPdfDto f=documents.generar(id);StreamResource r=new StreamResource(f.nombreArchivo(),()->new ByteArrayInputStream(f.contenido()));r.setContentType("application/pdf");r.setCacheTime(0);var x=VaadinSession.getCurrent().getResourceRegistry().registerResource(r);UI.getCurrent().getPage().open(x.getResourceUri().toString(),"_blank");}private void refresh(){catalogs=service.catalogos(null);warehouse.setItems(catalogs.almacenes());reason.setItems(catalogs.motivos());load();}
 private static void confirm(String title,String text,Runnable action){ConfirmDialog c=new ConfirmDialog();c.setHeader(title);c.setText(text);c.setCancelable(true);c.setCancelText("Cancelar");c.setConfirmText("Confirmar");c.addConfirmListener(e->action.run());c.open();}private static Div section(String title,Component...fields){Div s=new Div();s.addClassName("cc-form-section");H3 h=new H3(title);h.addClassName("cc-section-heading");Div f=new Div(fields);f.addClassName("cc-dialog-form");s.add(h,f);return s;}private static Dialog dialog(String title,int width){Dialog d=new Dialog();d.setHeaderTitle(title);d.setWidth("min("+width+"px, 96vw)");return d;}private static DatePicker date(String l){DatePicker d=new DatePicker(l);d.setLocale(new Locale("es","DO"));d.setPlaceholder("DD/MM/YYYY");d.setClearButtonVisible(true);return d;}private static Span badge(EstadoAjusteInventario s){Span b=new Span(s.getEtiqueta());b.getElement().getThemeList().add("badge "+(s==EstadoAjusteInventario.CONFIRMED?"success":s==EstadoAjusteInventario.CANCELLED?"error":s==EstadoAjusteInventario.REVERSED?"warning":"contrast"));return b;}private static <T>void select(ComboBox<T> c,UUID id){c.getListDataView().getItems().filter(x->Objects.equals(id,id(x))).findFirst().ifPresent(c::setValue);}private static UUID id(Object x){if(x instanceof ComboBox<?> c)x=c.getValue();if(x instanceof AjusteInventarioCatalogosDto.Almacen a)return a.id();if(x instanceof AjusteInventarioCatalogosDto.Motivo m)return m.id();return null;}private static String number(BigDecimal x){return x==null?"—":NUMBER.format(x);}private static String signed(BigDecimal x){if(x==null)return "—";return(x.signum()>0?"+":"")+NUMBER.format(x);}private static String display(String x){return x==null||x.isBlank()?"—":x;}private static String value(String x){return x==null?"":x;}private static String time(OffsetDateTime x){return x==null?"—":TIME.format(x.atZoneSameInstant(ZoneId.systemDefault()));}private static boolean can(String p){return TenantContext.principalActual().permisos().contains(p);}private static void error(RuntimeException e,String f){String m=e instanceof ReglaNegocioException||e instanceof RecursoNoEncontradoException?e.getMessage():f;Notification.show(m==null||m.isBlank()?f:m);}private record LineDraft(AjusteInventarioCatalogosDto.Producto product,BigDecimal quantity){}
}
